use std::fmt;

#[derive(Debug, PartialEq)]
enum DurationError {
    Empty,
    MissingNumber(char),
    MissingUnit(String),
    UnknownUnit(char),
    Overflow,
}

impl fmt::Display for DurationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DurationError::Empty => write!(f, "duration is empty"),
            DurationError::MissingNumber(u) => write!(f, "unit '{u}' has no number"),
            DurationError::MissingUnit(n) => write!(f, "number {n} has no unit"),
            DurationError::UnknownUnit(u) => write!(f, "unknown unit '{u}'"),
            DurationError::Overflow => write!(f, "duration is too long"),
        }
    }
}

impl std::error::Error for DurationError {}

fn parse_duration(text: &str) -> Result<u64, DurationError> {
    let text = text.trim();
    if text.is_empty() {
        return Err(DurationError::Empty);
    }
    let mut total: u64 = 0;
    let mut number = String::new();
    for c in text.chars() {
        if c.is_ascii_digit() {
            number.push(c);
            continue;
        }
        let factor = match c {
            'd' => 86_400,
            'h' => 3_600,
            'm' => 60,
            's' => 1,
            other => return Err(DurationError::UnknownUnit(other)),
        };
        if number.is_empty() {
            return Err(DurationError::MissingNumber(c));
        }
        let n: u64 = number.parse().map_err(|_| DurationError::Overflow)?;
        let part = n.checked_mul(factor).ok_or(DurationError::Overflow)?;
        total = total.checked_add(part).ok_or(DurationError::Overflow)?;
        number.clear();
    }
    if !number.is_empty() {
        return Err(DurationError::MissingUnit(number));
    }
    Ok(total)
}

fn total(texts: &[&str]) -> Result<u64, DurationError> {
    let mut sum: u64 = 0;
    for t in texts {
        sum = sum.checked_add(parse_duration(t)?).ok_or(DurationError::Overflow)?;
    }
    Ok(sum)
}

fn format_duration(seconds: u64) -> String {
    if seconds == 0 {
        return "0s".to_string();
    }
    let mut out = String::new();
    let mut rest = seconds;
    for (unit, size) in [('d', 86_400), ('h', 3_600), ('m', 60), ('s', 1)] {
        if rest >= size {
            out.push_str(&format!("{}{unit}", rest / size));
            rest %= size;
        }
    }
    out
}

unitTests:
test("valid durations", || {
    check_eq(parse_duration("1h30m"), Ok(5400));
    check_eq(parse_duration(" 45s "), Ok(45));
    check_eq(parse_duration("2h5m10s"), Ok(7510));
    check_eq(parse_duration("1d"), Ok(86_400));
    check_eq(parse_duration("1m1m"), Ok(120));
    check_eq(parse_duration("10s1h"), Ok(3610));
});

test("errors", || {
    check_eq(parse_duration(""), Err(DurationError::Empty));
    check_eq(parse_duration("h"), Err(DurationError::MissingNumber('h')));
    check_eq(parse_duration("5h12"), Err(DurationError::MissingUnit("12".to_string())));
    check_eq(parse_duration("3x"), Err(DurationError::UnknownUnit('x')));
    check_eq(parse_duration("99999999999999999999s"), Err(DurationError::Overflow));
    check_eq(parse_duration("999999999999999d"), Err(DurationError::Overflow));
});

test("messages", || {
    check_eq(DurationError::Empty.to_string(), "duration is empty");
    check_eq(DurationError::MissingNumber('m').to_string(), "unit 'm' has no number");
    check_eq(DurationError::MissingUnit("12".into()).to_string(), "number 12 has no unit");
    check_eq(DurationError::UnknownUnit('x').to_string(), "unknown unit 'x'");
    check_eq(DurationError::Overflow.to_string(), "duration is too long");
});

test("totals with ?", || {
    check_eq(total(&["1h", "30m", "45s"]), Ok(5445));
    check_eq(total(&["1h", "bad", "2x"]), Err(DurationError::UnknownUnit('b')));
    check_eq(total(&[]), Ok(0));
});

test("formatting", || {
    check_eq(format_duration(5410), "1h30m10s");
    check_eq(format_duration(0), "0s");
    check_eq(format_duration(90_061), "1d1h1m1s");
    check_eq(format_duration(3600), "1h");
});

